WITH unpacked AS (SELECT id, service, log_ts, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs WHERE log_ts < '2025-10-01') SELECT service, COUNT(*) AS event_count, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, MAX(log_ts) AS ended_at FROM unpacked GROUP BY service HAVING event_count > 1;
